B.aqW=new A.hz("gas","\ud638\ud761 \uae30\uccb4 \ubd84\uc11d\xb7\uc2dd\ubcc4\xb7\ud300 \ud655\uc778 \ubc0f \uac10\uc555\uacc4\ud68d \uc900\uc218\uc758 \uc911\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.")
B.aqP=new A.hz("plan","\uc2b9\uc778\ub41c \ub2e4\uc774\ube59 \uacc4\ud68d\xb7\uc218\uc2ec\xb7\uc2dc\uac04\uc744 \uc784\uc758\ub85c \ud655\ub300\ud558\uc9c0 \uc54a\uaca0\uc2b5\ub2c8\ub2e4.")
