B.aqT=new A.hz("emergency","\uc751\uae09\uad6c\uc870\xb7\uc7ac\uc555\uce58\ub8cc \uc811\uadfc \uc9c0\uc5f0 \uac00\ub2a5\uc131\uacfc \uc774\uc1a1 \uc870\uce58\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4.")
B.a1z=s([B.aqR,B.aqW,B.aqP,B.aqL,B.t8,B.ta,B.aqT,B.t9],t.OZ)
